\subsection{Proposed Solution for $(\mathcal{P}_4)$}
Next, we develop an SCA-based algorithm to find a stationary point of $(\mathcal{P}_4)$. At the $t$-th iteration, we first apply the Dinkelbach's algorithm to the fractional objective function~\eqref{eq:RSLM_obj}, yielding
\begin{equation}
\begin{split}
 \bar{\eta}^\mathrm{SLM}  (\mathbf{Q},\mathbf{P} ; & \mathbf{Q}^{(t-1)},  \mathbf{P}^{(t-1)}) = R_{\mathrm{sum}}^{\mathrm{SLM}} (\mathbf{Q}) 
 & - \eta^\mathrm{SLM} (\mathbf{Q}^{(t-1)},\mathbf{P}^{(t-1)}) P_{\mathrm{tot}}^{\mathrm{SLM}} (\mathbf{P}) ,
 \end{split}
 \label{eq:DB}
\end{equation}
where $\mathbf{Q}^{(t)}$ and $\mathbf{P}^{(t)}$ are the values of $\mathbf{Q}$ and $\mathbf{P}$ at the $t$-th iteration of the proposed algorithm. We then express $R_{\mathrm{sum}}^{\mathrm{SLM}} (\mathbf{Q})$ as
\begin{equation}
\begin{split}
 & R_{\mathrm{sum}}^{\mathrm{SLM}} (\mathbf{Q})  = \sum_{k\in \mathcal{K}}  \log_2 \bigg(\varpi^2
 \sum_{i\in \mathcal{K}}
 |\tilde{\mathbf{h}}_k^{\mathrm{H}}\mathbf{q}_i|^2
 +
 \varsigma_k(\mathbf{Q})

 &+
 \sigma_k^2 \bigg) - \log_2 \bigg(
 \varpi^2
 \sum_{i \in \mathcal{K} \setminus \{ k \}}
 |\tilde{\mathbf{h}}_k^{\mathrm{H}}\mathbf{q}_i|^2
 +
 \varsigma_k(\mathbf{Q})
 +
 \sigma_k^2 \bigg).
 \end{split}
 \label{eq:RSLM_SR1}
\end{equation}
Next, we define the slack variables $\boldsymbol{\alpha} \triangleq [\alpha_{1,1}, \dots,\alpha_{K,K} ]^\mathrm{T}$, $\boldsymbol{\beta} \triangleq [\beta_{1}, \dots,\beta_{K} ]^\mathrm{T}$ and $\boldsymbol{\zeta} \triangleq [\zeta_{1}, \dots,\zeta_{K} ]^\mathrm{T}$ such that
\begin{subequations}
\begin{align}
 \alpha_{k,i} & \leq |\tilde{\mathbf{h}}_k^{\mathrm{H}}\mathbf{q}_i|^2 \ \forall k,i \in \mathcal{K},
 \label{eq:NC1} 
 \beta_{k} & \leq \varsigma_k (\mathbf{Q}) \  \forall k \in \mathcal{K} ,
 \label{eq:NC2} 
 \zeta_k & \geq \varpi^2
 \sum_{i \in \mathcal{K} \setminus \{k \}}
 |\tilde{\mathbf{h}}_k^{\mathrm{H}}\mathbf{q}_i|^2
 +
 \varsigma_k(\mathbf{Q}) \ \forall k,i \in \mathcal{K}.
 \label{eq:NC3}
 \end{align}
\end{subequations}
Thus, we can lower-bound the sum rate as 
\begin{equation}
\begin{split}
 R_{\mathrm{sum}}^{\mathrm{SLM}} ( \mathbf{Q} )  \geq \sum_{k \in \mathcal{K}} \log_2(\varpi^2
 \sum_{i \in \mathcal{K}} &
 \alpha_{k,i}
 +
 \beta_k
 +
 \sigma_k^2) 
 & - \log_2 (
 \zeta_k
 +
 \sigma_k^2).
 \end{split}
 \label{eq:RSLM_SR2}
\end{equation}
It can be noted that the first term in the left-hand side in~\eqref{eq:RSLM_SR2} is already concave, while the second term needs to be linearized. To do so, we use the following surrogate function derived from the first-order Taylor expansion:
\begin{equation}
\begin{split}
\tilde{R}_{\mathrm{sum}}^{\mathrm{SLM}} (  \boldsymbol{\alpha} , \boldsymbol{\beta},\boldsymbol{\zeta} ; \boldsymbol{\zeta}^{(t-1)} ) & = \sum_{k \in \mathcal{K}}  \log_2\bigg(\varpi^2
 \sum_{i \in \mathcal{K}}
 \alpha_{k,i}
 + 
 \beta_k

 & 
 + \sigma_k^2\bigg) - \frac{1}{\ln 2} \ \frac{(\zeta_k - \zeta_k^{(t-1)})}{\zeta_k^{(t-1)} + \sigma^2_k}.
 \end{split}
 \label{eq:conv_expr}
\end{equation}
 The expression~\eqref{eq:conv_expr} is now concave in the optimization variables. Hence, a concave surrogate function on~\eqref{eq:DB} can be obtained as
\begin{equation}
\begin{split}
 &\tilde{\eta}^\mathrm{SLM}  (\mathbf{P}, \boldsymbol{\alpha} , \boldsymbol{\beta},\boldsymbol{\zeta} ; \mathbf{Q}^{(t-1)},  \mathbf{P}^{(t-1)}, \boldsymbol{\zeta}^{(t-1)}) = \tilde{R}_{\mathrm{sum}}^{\mathrm{SLM}} (  
 & \boldsymbol{\alpha}, \boldsymbol{\beta} , \boldsymbol{\zeta} ; \boldsymbol{\zeta}^{(t-1)} ) - \eta^\mathrm{SLM} (\mathbf{Q}^{(t-1)},\mathbf{P}^{(t-1)}) P_{\mathrm{tot}}^{\mathrm{SLM}} (\mathbf{P}).
 \end{split}
 \label{eq:DB_SF}
\end{equation}
Next, we note that the new constraint~\eqref{eq:NC3} is convex, while appropriate surrogate functions are needed to tackle the right-hand sides of~\eqref{eq:NC1} and~\eqref{eq:NC2}. Using the first-order Taylor series expansion, we can find surrogate functions to approximate~\eqref{eq:NC1} and~\eqref{eq:NC2} as
\begin{subequations}
\begin{align}
\alpha_{k,i} &\!\leq \!  2\Re\{\mathbf{q}_i^{\mathrm{H}}\tilde{\mathbf{h}}_k\tilde{\mathbf{h}}_k^{\mathrm{H}}\mathbf{q}_i^{(t-1)}\}
\! -\! \left|\tilde{\mathbf{h}}_k^{\mathrm{H}}\mathbf{q}_i^{(t-1)}\right|^2 \! \! \! ,\ \forall i,k\in\mathcal{K} \!, \label{eq:NC4}
\beta_k &\leq 2\Re\{\tilde{\mathbf{h}}_k^{\mathrm{H}}\mathbf{Q}\mathbf{Q}^{(t-1)\mathrm{H}}\tilde{\mathbf{h}}_k\}
-\|\mathbf{Q}^{(t-1)\mathrm{H}}\tilde{\mathbf{h}}_k\|_2^2,\ \forall k\in\mathcal{K}, \label{eq:NC5}
\end{align}
\end{subequations}
which are both convex in the optimization variables.
Next, we tackle the constraints~\eqref{eq:RSLM_PB} and~\eqref{eq:RSLM_PSD}. While the former is already convex, the latter can be expressed in a convex linear matrix inequality (LMI) format as
\begin{equation}
\begin{bmatrix}
\text{diag} (p_1,\dots,p_K) & \mathbf{Q}^{\mathrm H}
\mathbf{Q} & \mathbf{I}_V
\end{bmatrix}
\succeq \mathbf{0},
\label{eq: SPD_conv}
\end{equation}
which is convex in $\mathbf{Q}$ and $\mathbf{P}$.
Next, we tackle the constraint set~\eqref{eq:RSLM_QoS} by first expressing the $k$-th user's rate constraint as
\begin{equation}
 |\tilde{\mathbf{h}}_k^{\mathrm{H}}\mathbf{q}_k|^2 \! \geq \! (2^r-1)\bigg(\varpi^2
 \! \! \! \! \sum_{i\in \mathcal{K} \setminus \{k\}}
 |\tilde{\mathbf{h}}_k^{\mathrm{H}}\mathbf{q}_i|^2
 +
 \varsigma_k(\mathbf{Q})
 +
 \sigma_k^2\bigg).
 \label{eq:QoS_for}
\end{equation}
We can observe that the right-hand side of~\eqref{eq:QoS_for} is convex, and the left-hand side can be tackled using~\eqref{eq:NC1}, leading to
\begin{equation}
 \alpha_{k,k} \geq (2^r-1)\bigg(\varpi^2
 \sum_{i\in \mathcal{K} \setminus \{k\}}
 |\tilde{\mathbf{h}}_k^{\mathrm{H}}\mathbf{q}_i|^2
 +
 \varsigma_k(\mathbf{Q})
 +
 \sigma_k^2\bigg) \ \forall k \in \mathcal{K}.
 \label{eq:NC6}
\end{equation}
Thus, the convex SCA subproblem at the $t$-th iteration is given by
\begin{subequations}
\label{eq:SCA_SLM}
\begin{align}  \underset{\mathbf{Q},\mathbf{P}, \boldsymbol{\alpha}, \boldsymbol{\beta}, \boldsymbol{\zeta}}{\max}\  & \tilde{\eta}^\mathrm{SLM}  (\mathbf{P},  \boldsymbol{\alpha} , \boldsymbol{\beta}, \boldsymbol{\zeta} ; \mathbf{Q}^{(t-1)},  \mathbf{P}^{(t-1)}, \boldsymbol{\zeta}^{(t-1)}) \label{eq:SOF} 
\text{s.t.} \ & \eqref{eq:RSLM_PB}, \eqref{eq:NC3}, \eqref{eq:NC4}, \eqref{eq:NC5}, \eqref{eq: SPD_conv}, \eqref{eq:NC6}. 
\end{align}
\end{subequations}
This problem is convex and can be solved using the numerical optimization algorithms, e.g., via the CVX toolbox~\cite{2014_Grant}.
