 \caption{Normalized EE versus the number of antennas achieved by the proposed algorithm (solid) and the low-dimensional closed-form search (dashed) as the number of transmit antennas increases. Horizontal lines indicate the corresponding asymptotic scaling constants.}
 \label{fig:vary_N2}
 \end{minipage}
